function setup(id){const c=$('#'+id),g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);g.lineCap=g.lineJoin='round';return[c,g]}function mean(a,k){const v=a.map(x=>x[k]).filter(Number.isFinite);return v.length?v.reduce((s,x)=>s+x,0)/v.length:NaN}
function metrics(data,time=null){const cadence=Number.isFinite(data.cadence)?data.cadence:result?.cadence;$('#cadenceValue').textContent=$f(cadence);$('#stepCountValue').textContent=data.events.length;$('#stepTimeValue').textContent=$f(data.stepTime*1000);$('#contactValue').textContent=$f(data.contactTime*1000);$('#qualityLabel').textContent=data.quality>=80?'良好':data.quality>=60?'可用':'需複核';$('#qualityBar').style.width=data.quality+'%';$('#qualityText').textContent=time===null?`姿態可見度 ${data.quality}/100；共 ${data.events.length} 次觸地。`:`播放至 ${clockP(time)} · ${data.events.length} 次觸地。`;syncTimelines(time??0);dashboard(data,time)}
function renderResult(){metrics(result);renderChart();renderTable();renderRaw();for(const id of['downloadCsv','downloadJson','downloadReport','shareReport'])$('#'+id).disabled=false;configureTimelines()}function playback(t,force=false){if(!result||!playbackSyncActive)return;let i=result.frames.findIndex(f=>f.time>=t);if(i<0)i=result.frames.length-1;if(!force&&i===lastDashboardFrame)return;lastDashboardFrame=i;metrics(summarizeUntil(result,t),t);status(`同步播放 · ${clockP(t)}`)}
