function cadenceChart(data,time){const[c,g]=setup('cadenceCanvas'),duration=result.frames.at(-1)?.time||1,pts=[];for(let i=1;i<data.events.length;i++){const dt=data.events[i].time-data.events[i-1].time;if(dt>.15&&dt<1.2)pts.push({t:data.events[i].time,v:60/dt})}if(!pts.length&&Number.isFinite(result.cadence))pts.push({t:0,v:result.cadence},{t:Math.min(time??duration,duration),v:result.cadence});const current=pts.at(-1)?.v??result.cadence,vals=[result.cadence,...pts.map(p=>p.v)].filter(Number.isFinite),min=Math.floor((Math.min(...vals,150)-10)/10)*10,max=Math.ceil((Math.max(...vals,170)+10)/10)*10,x=t=>55+t/duration*(c.width-75),y=v=>c.height-32-(v-min)/(max-min)*(c.height-46);g.strokeStyle='#303638';g.fillStyle='#777';g.font='11px system-ui';for(let i=0;i<4;i++){const v=min+(max-min)*i/3;g.beginPath();g.moveTo(55,y(v));g.lineTo(c.width-18,y(v));g.stroke();g.fillText(Math.round(v),5,y(v)+4)}g.strokeStyle='#2f80ed';g.lineWidth=5;g.beginPath();pts.forEach((p,i)=>i?g.lineTo(x(p.t),y(p.v)):g.moveTo(x(p.t),y(p.v)));g.stroke();g.fillStyle='#f2f7f5';g.font='800 22px system-ui';g.fillText(`${$f(current)} spm`,c.width-140,28);g.font='10px system-ui';g.fillStyle='#858b88';g.fillText('每一步的即時步頻',c.width-140,43);if(time!==null){g.strokeStyle='#b7f34a';g.beginPath();g.moveTo(x(time),12);g.lineTo(x(time),c.height-32);g.stroke()}}
