input.onchange=e=>{loadVideo(e.target.files[0]);input.value=''};$('#replaceVideo').onclick=()=>input.click();$('#analyzeButton').onclick=analyze;$('#togglePlayback').onclick=()=>video.paused?video.play():video.pause();$('#frameBack').onclick=()=>{playbackSyncActive=true;video.pause();video.currentTime=Math.max(0,video.currentTime-1/(result?.meta.sampleRate||30));playback(video.currentTime,true)};$('#frameForward').onclick=()=>{playbackSyncActive=true;video.pause();video.currentTime=Math.min(video.duration,video.currentTime+1/(result?.meta.sampleRate||30));playback(video.currentTime,true)};$('#toggleOverlay').onclick=e=>{overlayVisible=!overlayVisible;e.currentTarget.classList.toggle('active',overlayVisible);if(!overlayVisible)ctx.clearRect(0,0,canvas.width,canvas.height);lastFrame=null};$('#downloadJson').onclick=()=>download('running-gait-analysis.json','application/json',JSON.stringify(result,null,2));$('#downloadCsv').onclick=()=>{const rows=[['time_seconds','left_foot_clearance_norm','right_foot_clearance_norm','left_contact','right_contact','left_hip_deg','right_hip_deg','left_knee_flexion_deg','right_knee_flexion_deg','com_y_norm'],...rawRows().map(r=>[r.time.toFixed(4),$f(r.leftHeight,6),$f(r.rightHeight,6),r.leftContact?1:0,r.rightContact?1:0,$f(r.leftHip,3),$f(r.rightHip,3),$f(r.leftKnee,3),$f(r.rightKnee,3),$f(r.comY,6)])];download('running-gait-raw-data.csv','text/csv','\ufeff'+rows.map(r=>r.join(',')).join('\n'))};$('#downloadReport').onclick=()=>download('running-gait-report.html','text/html',reportHtml());$('#shareReport').onclick=()=>shareReport().catch(e=>{if(e.name!=='AbortError')toast('分享未完成，請先下載報告後由 LINE 附加')});video.onplay=()=>{playbackSyncActive=!!result;lastDashboardFrame=-1;$('#togglePlayback .material-symbols-rounded').textContent='pause';playback(video.currentTime,true)};video.onpause=()=>{$('#togglePlayback .material-symbols-rounded').textContent='play_arrow';playback(video.currentTime,true)};video.ontimeupdate=()=>{$('#videoTime').textContent=`${clockP(video.currentTime)} / ${clock(video.duration)}`;playback(video.currentTime)};video.onseeking=()=>{lastFrame=null;if(result){playbackSyncActive=true;playback(video.currentTime,true)}};for(const id of['viewSide','runDirection','athleteHeight'])$('#'+id).onchange=()=>{if(result){metrics(playbackSyncActive?summarizeUntil(result,video.currentTime):result,playbackSyncActive?video.currentTime:null);renderTable();renderRaw()}};window.onresize=syncOverlay;['dragenter','dragover'].forEach(n=>document.addEventListener(n,e=>e.preventDefault()));document.ondrop=e=>{e.preventDefault();const f=[...e.dataTransfer.files].find(isVideo);if(f)loadVideo(f)};overlay();

